#/bin/bash
# ============================================================================
# harden_payment_edit_concurrency.sh
#
# Hardens the Receipt Register "Edit" flow (payments/receipt/receipt-tab.js)
# against the bug that let repeated/overlapping edits stack payment_modes
# rows instead of cleanly replacing them (root cause of the Satya Pal Singh
# duplicate-refund cash/UPI corruption fixed directly in the database).
#
# NOTE: The server-side fix (edit_payment_clerical SQL function -- adds an
# optimistic-concurrency check plus a post-write sum verification) has
# ALREADY been applied directly to both Supabase projects (production
# flzysyzhaecaqbmdcuao and training ffaddzpwnbizhvhujlse) via migration.
# No SQL needs to run from this script -- this only ships the matching
# frontend changes.
#
# CHANGES:
#   MODIFIED: app/(main)/payments/actions.js
#     - editPaymentClerical() now accepts and forwards expectedModeCount
#       to the hardened RPC.
#   MODIFIED: app/(main)/payments/receipt/receipt-tab.js
#     - "Edit" now always fetches the payment fresh via getReceiptById()
#       instead of reusing the (possibly stale) row from the last search --
#       this was how a prior edit's result got missed and compounded on.
#     - Save is guarded by a ref (savingRef) in addition to the existing
#       disabled-while-saving button, blocking a double-submit that fires
#       before React re-renders.
#     - The freshly-fetched mode count is sent to the server as
#       expectedModeCount -- if the database's actual mode-row count has
#       changed since the edit form opened, the save is now rejected with
#       a clear "refresh and try again" message instead of silently
#       stacking.
#
# Run this from the root of your veda-hmis repo in GitHub Codespaces.
# ============================================================================

set -e

echo "==> Payment-edit concurrency hardening"
echo ""

if [ ! -f "package.json" ] || [ ! -d "app" ]; then
  echo "ERROR: This doesn't look like the veda-hmis repo root (no package.json / app dir found)."
  echo "cd into your repo root and re-run this script."
  exit 1
fi

echo "==> Overwriting app/(main)/payments/actions.js"
echo "" | base64 -d > "app/(main)/payments/actions.js"

echo "==> Overwriting app/(main)/payments/receipt/receipt-tab.js"
echo "" | base64 -d > "app/(main)/payments/receipt/receipt-tab.js"

echo ""
echo "==> Files written. Verifying build..."
if command -v npm >/dev/null 2>&1; then
  npm run build || { echo "BUILD FAILED -- check output above before pushing."; exit 1; }
else
  echo "npm not found -- skipping build verification, run 'npm run build' manually."
fi

echo ""
echo "==> Done. Review changes with: git status && git diff"
echo "==> To deploy, run:"
echo "    git add -A"
echo '    git commit -m "Harden payment edit against stale-state/double-submit mode stacking"'
echo "    git push"
